// A Map (hidden class) is modeled by the ORDERED key list a construction path produces.
function mapSig(o) {
  // Object.keys preserves insertion order for string keys -> models the transition path / leaf Map.
  return Object.keys(o).join(',');
}

// Factory: always x, then y, then z.
function viaFactory() {
  const o = {};
  o.x = 1; o.y = 2; o.z = 3;
  return o;
}
// Literal: same fields, same order -> same construction path -> same Map.
function viaLiteral() {
  return { x: 10, y: 20, z: 30 };
}
// Reversed: z, then y, then x -> a different leaf Map.
function viaReversed() {
  const o = {};
  o.z = 3; o.y = 2; o.x = 1;
  return o;
}

const maps = new Set();
maps.add(mapSig(viaFactory()));
maps.add(mapSig(viaLiteral()));
maps.add(mapSig(viaReversed()));
console.log('distinctMaps=' + maps.size);
